import { Router, Request, Response } from "express";
import fs from "fs";
import path from "path";
import { prisma } from "../db/prisma";
import { requireAuth } from "../middlewares/auth";
import { ensureExtraPracticeProblem, slugFromLink, SLUG_RE } from "../services/leetcodeImportService";

/**
 * Built-in catalog of established LeetCode roadmaps (Blind 75, NeetCode 150,
 * Grind 75, LeetCode 75, ...). Data is generated by scripts/fetch-roadmaps.mjs
 * into backend/data/roadmaps.json and merged here with the user's progress.
 */

export interface CatalogProblem {
  slug: string;
  title: string;
  difficulty: "EASY" | "MEDIUM" | "HARD";
}
export interface CatalogRoadmap {
  slug: string;
  name: string;
  author: string;
  source: string;
  kind: "community" | "official" | "company";
  description: string;
  estimatedWeeks: number;
  problemCount: number;
  sections: Array<{ name: string; problems: CatalogProblem[] }>;
}

let cache: CatalogRoadmap[] | null = null;
export const loadCatalog = (): CatalogRoadmap[] => {
  if (cache) return cache;
  // ts-node: routes/ -> ../data ; compiled: dist/routes/ -> ../../data
  const candidates = [path.join(__dirname, "../data/roadmaps.json"), path.join(__dirname, "../../data/roadmaps.json")];
  const file = candidates.find((p) => fs.existsSync(p));
  cache = file ? (JSON.parse(fs.readFileSync(file, "utf8")).roadmaps as CatalogRoadmap[]) : [];
  return cache;
};

/** slug -> { problemId, solved } for this user, from tracker problems + progress. */
const userSlugIndex = async (userId: string) => {
  const [problems, done] = await Promise.all([
    prisma.problem.findMany({ select: { id: true, link: true } }),
    prisma.progress.findMany({ where: { userId, status: "DONE" }, select: { problemId: true } }),
  ]);
  const doneIds = new Set(done.map((d) => d.problemId));
  const index = new Map<string, { problemId: string; solved: boolean }>();
  for (const p of problems) {
    const slug = slugFromLink(p.link);
    if (!slug) continue;
    const prev = index.get(slug);
    // Prefer the entry that is solved if a slug appears twice.
    if (!prev || (!prev.solved && doneIds.has(p.id))) index.set(slug, { problemId: p.id, solved: doneIds.has(p.id) });
  }
  return index;
};

const router = Router();

router.get("/roadmaps", requireAuth, async (req: Request, res: Response) => {
  try {
    const index = await userSlugIndex(req.user!.id);
    res.json(
      loadCatalog().map((r) => {
        const slugs = r.sections.flatMap((s) => s.problems.map((p) => p.slug));
        const solved = slugs.filter((s) => index.get(s)?.solved).length;
        const byDifficulty = { EASY: 0, MEDIUM: 0, HARD: 0 };
        for (const s of r.sections) for (const p of s.problems) byDifficulty[p.difficulty] += 1;
        return {
          slug: r.slug,
          name: r.name,
          author: r.author,
          source: r.source,
          kind: r.kind,
          description: r.description,
          estimatedWeeks: r.estimatedWeeks,
          problemCount: r.problemCount,
          sectionCount: r.sections.length,
          byDifficulty,
          solved,
        };
      }),
    );
  } catch (err) {
    console.error("Roadmap catalog error:", err);
    res.status(500).json({ error: "Failed to load roadmaps" });
  }
});

router.get("/roadmaps/:slug", requireAuth, async (req: Request, res: Response) => {
  try {
    const roadmap = loadCatalog().find((r) => r.slug === req.params.slug);
    if (!roadmap) return res.status(404).json({ error: "Roadmap not found" });
    const index = await userSlugIndex(req.user!.id);
    let solved = 0;
    const sections = roadmap.sections.map((s) => ({
      name: s.name,
      problems: s.problems.map((p) => {
        const hit = index.get(p.slug);
        if (hit?.solved) solved += 1;
        return { ...p, problemId: hit?.problemId ?? null, solved: Boolean(hit?.solved) };
      }),
    }));
    res.json({ ...roadmap, sections, solved });
  } catch (err) {
    console.error("Roadmap detail error:", err);
    res.status(500).json({ error: "Failed to load roadmap" });
  }
});

/**
 * Makes a roadmap problem available in the tracker's workspace (adds it under
 * Extra Practice if it isn't part of the curriculum) and returns its id.
 */
router.post("/roadmaps/problems/:slug/open", requireAuth, async (req: Request, res: Response) => {
  try {
    const slug = String(req.params.slug).toLowerCase();
    if (!SLUG_RE.test(slug)) return res.status(400).json({ error: "Invalid slug" });
    const known = loadCatalog()
      .flatMap((r) => r.sections.flatMap((s) => s.problems))
      .find((p) => p.slug === slug);
    if (!known) return res.status(404).json({ error: "Not part of any roadmap" });

    const existing = await prisma.problem.findFirst({
      where: { OR: [{ link: { contains: `/problems/${slug}/` } }, { link: { endsWith: `/problems/${slug}` } }] },
      select: { id: true },
    });
    const problem = existing ?? (await ensureExtraPracticeProblem(slug, known.title, known.difficulty));
    res.json({ problemId: problem.id });
  } catch (err) {
    console.error("Roadmap open problem error:", err);
    res.status(500).json({ error: "Failed to open problem" });
  }
});

export default router;
